    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // The one permitted fetch. A transport failure is a value, not a trap,
        // so it reports zero characters rather than failing the run.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} characters");
        let notified = notifier::notify(&message);

        // ensures notified == true: a refused notification must not yield an output.
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
